 '16':['15','17','20','21'],
 '17':['16','18','21'],
 '18':['17','21','25','26'],
 '19':['11','13','14','20','22'],
 '20':['10','11','15','16','19','21','22','23'],
 '21':['16','17','18','20','23','24','25'],
 '22':['14','19','20','23'],
